SELECT *
FROM search_doc_index
WHERE biz_type = #{bizType}
  AND status = 1
  AND is_deleted = 0
  AND (
    search_text_normalized = #{normalizedQuery}
    OR author_name = #{normalizedQuery}
    OR category_name = #{normalizedQuery}
    OR tag_names_text = #{normalizedQuery}
  )
ORDER BY hot_score DESC, quality_score DESC, updated_time DESC
LIMIT #{limit}
